/* ---------- L6M3 — A checklist ---------- */
function renderC19Checklist(){return c19P('lgr',
  'The last module is practical: a <b>checklist</b> you can walk through on your own network or on a topology in the simulator. It is split into four areas and deliberately short, because a list that cannot be walked in twenty minutes will not be walked. <b>Collection.</b> Do you have a log server? Do <b>all</b> active devices send records to it – firewall, router, switch, IDS – not just the ones someone remembered? Do the devices share <b>a common time</b> so a timeline can be assembled? <b>Path.</b> Does a report from <b>every</b> segment reach the log server, that is, is port 514 still permitted after the last tightening of rules? Does the Syslog panel show <b>zero lost</b> events? Is some segment silent without you knowing why? <b>Content.</b> Do you log denials, alerts, state changes and failed logins – and conversely not passwords or message contents? Does every critical event have <b>a written procedure</b> for what to do? <b>Attention.</b> Does anyone really look at the alerts, or do they merely drop into a folder? What share of alerts led to an action? Do you know your <b>baseline</b> and when it was last updated? A last piece of advice worth taking from the whole course: monitoring is not a project with an end. A new application, a new rule, a new segment – every network change also changes what you see and what you do not. So the list is walked <b>regularly</b>, not once at rollout. And if a single sentence survives the course, let it be this one: <b>what you do not collect you do not see, and what you do not see you cannot investigate</b>.',
  [['checklist','four areas: collection, path, content and attention; walked regularly, not once.'],['attention','the weakest link of monitoring: does anyone really look, and does it lead to action?']])
  +courseCTA('lgrTask','Build a network with an IDS and see what appears in the Syslog panel: the challenge "Network with detection".','Open the challenge');}
function mountC19Checklist(){c19Mount('lgr',[
  {glow:c19g('pc','--green')+c19g('sw','--green')+c19g('fw','--green')+c19g('log','--green'),dyn:c19pkt('M 60 90 L 190 165 L 320 165 L 450 60','--green')+c19lbl('collection: log server, all devices, a common time','--green'),cap:'<b>Collection</b>: do you have a log server? Do <b>all</b> active devices send to it? Do they share a common time?'},
  {glow:c19g('gst','--amber')+c19g('sw','--amber')+c19g('fw','--amber')+c19g('log','--amber'),dyn:c19pkt('M 60 240 L 190 165 L 320 165 L 450 60','--amber')+c19lbl('path: port 514 permitted and zero lost events','--amber'),cap:'<b>Path</b>: does a report from every segment reach the server? Is port 514 still permitted after tightening? Are losses <b>zero</b>?'},
  {glow:c19g('ids','--blue')+c19g('fw','--blue')+c19g('log','--blue'),dyn:c19pkt('M 450 270 L 320 165 L 450 60','--blue')+c19lbl('content: denials, alerts, state changes – and no passwords','--blue'),cap:'<b>Content</b>: do you log denials, alerts, state changes and failed logins – and not passwords? Does a critical event have a procedure?'},
  {glow:c19g('log','--cyan')+c19g('fw','--cyan')+c19g('net','--cyan'),dyn:c19pkt('M 450 60 L 320 165 L 590 165','--cyan')+c19lbl('attention: does anyone look, and do you know your baseline?','--cyan'),cap:'<b>Attention</b>: does anyone really look? How many alerts led to action? What you do not collect you do not see – and cannot investigate.'}
]);
  var b=$('lgrTask');if(b)b.onclick=function(){courseTry('ch-ids');};
}

